[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::ProductPriceGroup, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeProductPriceGroup extends UPSPricingAttributePriceGroup implements UPSIPricingAttribute
