}

Method.Source:
public Set getAllowedValues()
{
    var valueSet = new Set(Types::String);

    UPSPricingAttributeGroup upsPricingAttributeGroup;

    while select upsPricingAttributeGroup
        where upsPricingAttributeGroup.GroupType == UPSPricingAttributeGroupType::Product
        && upsPricingAttributeGroup.IsValid == NoYes::Yes
    {
        valueSet.add(upsPricingAttributeGroup.Name);
    }

    return valueSet;
}

public void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, CustGroup));
    qbr.value(queryValue(_value));
}
